// Enrutador de eventos de PorteriaYa.
//
// La app publica TODOS los eventos a un unico webhook (porteria.n8n.webhook-url),
// asi que algo tiene que repartirlos. Este flujo es ese reparto y nada mas:
// valida el secreto compartido (§10) y reenvia el evento intacto al flujo que le
// toca. No redacta mensajes ni decide reglas de negocio.
//
// Se reenvia por HTTP a webhooks con nombre, y no con nodos Execute Workflow,
// para que no haya que cablear IDs de workflow a mano despues de importar.

const esperado = $env.PORTERIA_SECRET;

const DESTINO = {
  // §14.1 Visitas
  AUTORIZACION_CREADA: 'porteriaya-visitas',
  INGRESO_REGISTRADO: 'porteriaya-visitas',

  // §14.2 Aprobacion en vivo
  VISITA_NO_ANUNCIADA: 'porteriaya-aprobacion',

  // §14.3 Paquetes
  PAQUETE_RECIBIDO: 'porteriaya-paquetes',
  PAQUETE_RECORDATORIO: 'porteriaya-paquetes',
  PAQUETE_ESCALADO: 'porteriaya-paquetes',

  // §14.4 Alertas de seguridad
  PERSONA_NO_PERMITIDA: 'porteriaya-alertas',
  PERMANENCIA_EXCEDIDA: 'porteriaya-alertas',
  SALIDA_NO_REGISTRADA: 'porteriaya-alertas',

  // §10 emite estos dos, pero §14 no les asigna flujo. Van al mismo sitio
  // porque tienen el mismo destinatario (administracion); el flujo 04 los
  // marca como aviso y no como alerta, para que no suenen igual.
  DOCUMENTO_INDEXADO: 'porteriaya-alertas',
  RAG_SIN_RESPUESTA: 'porteriaya-alertas',
};

const salida = [];

for (const item of $input.all()) {
  const cabeceras = item.json.headers || {};
  const evento = item.json.body || item.json;

  // El secreto compartido de §10. Si no cuadra, no se reenvia nada.
  if (esperado) {
    const recibido = cabeceras['x-porteria-secret'] || cabeceras['X-Porteria-Secret'];
    if (recibido !== esperado) {
      throw new Error('X-Porteria-Secret invalido: evento descartado');
    }
  }

  const destino = DESTINO[evento.tipo];
  if (!destino) {
    // Un tipo de evento nuevo no debe tumbar el enrutador: queda en el log
    // de la ejecucion y se ignora.
    console.log('Evento sin flujo asignado, se ignora: ' + evento.tipo);
    continue;
  }

  salida.push({ json: { destino, evento } });
}

return salida;
